def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    original = {"id": "a", "day": 4, "flagged": True}
    replacement = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier = {"id": "z", "day": 1, "flagged": True}
    assert dedupe_transcripts([original, same_day, earlier, replacement]) == [
